python3 -c "from pathlib import Path;
workers=['carapace-light.md','carapace-medium.md','carapace-heavy.md','carapace-careful.md','carapace-fable.md'];
for name in workers:
 fm=Path('agents',name).read_text().split('---',2)[1];
 tools=next(l for l in fm.splitlines() if l.startswith('tools:'));
 assert 'Agent' not in tools and 'mcp__carapace__step' in tools, name;
adv=next(l for l in Path('agents/carapace-advisor.md').read_text().split('---',2)[1].splitlines() if l.startswith('tools:'));
assert 'Agent' not in adv"
